morse.watch("body", el => {
  if (el.dataset.cKeyBound) return;
  el.dataset.cKeyBound = "1";
  morse.on(document, "keydown", e => {
    const t = e.target;
    if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (e.key !== "c" && e.key !== "C") return;
    const btn = morse.$('button[aria-label="Clear\\ canvas"]') || morse.$('button[aria-label="Clear canvas"]');
    if (btn) { e.preventDefault(); btn.click(); morse.toast("Canvas cleared"); }
  });
});

