results.js:
morse.watch('[aria-label="Tools"]', tools => {
  const btn = morse.el('button', {
    class: 'morse-save-png',
    'aria-label': 'Save as PNG',
    title: 'Save as PNG',
    text: '💾',
    on: {
      click: () => {
        const board = document.getElementById('board');
        if (!board) return;
        board.toBlob(blob => {
          if (!blob) return;
          const url = URL.createObjectURL(blob);
          const a = morse.el('a', { href: url, download: 'sketch.png' });
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(url), 1000);
          morse.toast('Saved sketch.png');
        }, 'image/png');
      }
    }
  });
  tools.appendChild(btn);
});

