const btn = morse.el("button", {
  id: "morse-totop",
  type: "button",
  "aria-label": "Back to top",
  title: "Back to top",
  text: "↑",
  on: { click: () => window.scrollTo({ top: 0, behavior: "smooth" }) }
});
document.body.appendChild(btn);

const update = () => {
  btn.style.display = window.scrollY > 300 ? "block" : "none";
};
morse.on(window, "scroll", update);
update();

let pending = null;

function askDelete(title, onYes) {
  document.querySelectorAll('.morse-confirm').forEach(n => n.remove());
  const cancel = morse.el('button', {
    text: 'Cancel',
    style: 'border:1px solid #d4d4d8;background:#fff;color:inherit;border-radius:6px;padding:6px 12px;cursor:pointer;font:inherit',
    on: { click: () => overlay.remove() }
  });
  const ok = morse.el('button', {
    text: 'Delete',
    style: 'border:0;background:#dc2626;color:#fff;border-radius:6px;padding:6px 12px;cursor:pointer;font:inherit',
    on: { click: () => { overlay.remove(); onYes(); } }
  });
  const box = morse.el('div', {
    style: 'background:#fff;color:#18181b;border-radius:10px;padding:16px;width:300px;font:inherit;box-shadow:0 10px 30px rgba(0,0,0,.2)'
  },
    morse.el('div', { text: 'Delete "' + title + '"?', style: 'font-weight:600;margin-bottom:12px' }),
    morse.el('div', { style: 'display:flex;gap:8px;justify-content:flex-end' }, cancel, ok)
  );
  const overlay = morse.el('div', {
    class: 'morse-confirm',
    style: 'position:fixed;inset:0;background:rgba(0,0,0,.3);display:flex;align-items:center;justify-content:center;z-index:9999',
    on: { click: e => { if (e.target === overlay) overlay.remove(); } }
  }, box);
  document.body.appendChild(overlay);
}

morse.watch('button.del[data-id]', el => {
  morse.on(el, 'click', e => {
    if (pending === el) { pending = null; return; }
    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();
    const card = el.closest('article.card');
    const title = (card && card.querySelector('label') || {}).textContent?.trim() || 'this task';
    askDelete(title, () => { pending = el; el.click(); });
  });
});

