function sync() {
  const hdr = morse.$("#root > header.hdr");
  if (!hdr || !hdr.firstElementChild) return;
  let badge = hdr.querySelector(".tasky-left");
  if (!badge) {
    badge = morse.el("span", { class: "tasky-left" });
    hdr.firstElementChild.after(badge);
  }
  const left = morse.$$("div.board input[type=checkbox]").filter(i => !i.checked).length;
  const text = left + " left";
  if (badge.textContent !== text) badge.textContent = text;
}
morse.watch("#root > header.hdr", sync, { live: true });
morse.watch("div.board", sync, { live: true });
morse.on(document, "change", sync);

