results.js:
morse.watch('div[aria-label="Log\\ lines"] > div.sz > div.row', (row) => {
  if (row.querySelector(':scope > .morse-copy')) return;
  const btn = morse.el('button', { class: 'morse-copy', text: 'Copy' });
  morse.on(btn, 'click', (e) => {
    e.stopPropagation();
    const f = (s) => row.querySelector(':scope > span.' + s)?.textContent ?? '';
    const line = [f('ts'), f('lv'), f('svc'), f('msg')].join(' ');
    navigator.clipboard.writeText(line).then(
      () => morse.toast('Line copied'),
      () => morse.toast('Copy failed')
    );
  });
  row.appendChild(btn);
}, { live: true });

